+
+// find returns the index of the interned list with the given fingerprint that is the same as dataList.
+func (v *complexSemtypeInternValues) find(fingerprint uint64, dataList []properSubtypeData) (int, bool) {
+	for entry := v.fingerprintHeads[fingerprint]; entry != 0; entry = v.fingerprintNext[entry-1] {
+		if sameSubtypeDataList(v.dataLists[entry-1], dataList) {
+			return int(entry - 1), true
 		}
 	}
 	return 0, false
 }

+// subtypeDataListFingerprint returns a hash of dataList such that lists equal under sameSubtypeDataList
+// have equal hashes. It reports false when dataList contains data that is never the same as any other data,
+// in which case dataList cannot equal any other list.
+func (i *SemTypeInterner) subtypeDataListFingerprint(dataList []properSubtypeData) (uint64, bool) {
+	h := uint64(len(dataList))
+	for _, data := range dataList {
+		var elem uint64
+		switch d := data.(type) {
+		case nil:
+			elem = 0
+		case intSubtype, floatSubtype, decimalSubtype, stringSubtype:
+			return 0, false
+		case *bddNodeImpl:
+			elem = maphash.Comparable(i.seed, d)
+		case *bddNodeSimple:
+			elem = maphash.Comparable(i.seed, d)
+		case bddAllOrNothing:
+			elem = maphash.Comparable(i.seed, d)
+		case *xmlSubtype:
+			elem = maphash.Comparable(i.seed, d)
+		case booleanSubtype:
+			elem = maphash.Comparable(i.seed, d)
+		default:
+			// Hashing an unknown dynamic type could panic if it is not comparable; equal data always has
+			// the same dynamic type, so hashing the type alone stays consistent with sameSubtypeData.
+			elem = maphash.Comparable(i.seed, reflect.TypeOf(d))
+		}
+		h = (h ^ elem) * 0x100000001b3
+	}
+	return h, true
+}
+
 func basicInternHandle(bits basicTypeBitSet) InternHandle {
 	return InternHandle(-int(bits) - 1)
 }
